( function () {
'use strict';
var data = null;
function areaData() {
if ( data ) {
return data;
}
var el = document.getElementById( 'meeha-area-data' );
try {
data = el ? JSON.parse( el.textContent ) : {};
} catch ( e ) {
data = {};
}
data.d = data.d || {};
data.u = data.u || {};
return data;
}
function fill( select, list, placeholder ) {
if ( ! select ) {
return;
}
var first = select.options.length ? select.options[ 0 ].textContent : placeholder;
select.innerHTML = '';
var opt = document.createElement( 'option' );
opt.value = '';
opt.textContent = first || placeholder;
select.appendChild( opt );
( list || [] ).forEach( function ( name ) {
var o = document.createElement( 'option' );
o.value = name;
o.textContent = name;
select.appendChild( o );
} );
}
function target( el ) {
var id = el.getAttribute( 'data-target' );
return id ? document.getElementById( id ) : null;
}
var timers = new WeakMap();
function load( form ) {
var results = form.querySelector( '[data-area-results]' );
var endpoint = form.getAttribute( 'data-endpoint' );
if ( ! results || ! endpoint || ! window.fetch ) {
return;
}
var q = new URLSearchParams();
var div = form.querySelector( '.meeha-area-division' );
var dis = form.querySelector( '.meeha-area-district' );
var upz = form.querySelector( '.meeha-area-upazila' );
q.set( 'division', div ? div.value : '' );
q.set( 'district', dis ? dis.value : '' );
q.set( 'upazila', upz ? upz.value : '' );
q.set( 'count', form.getAttribute( 'data-count' ) || '5' );
q.set( 'tag', form.getAttribute( 'data-item-tag' ) || 'h4' );
results.setAttribute( 'aria-busy', 'true' );
results.style.opacity = '.55';
fetch( endpoint + ( endpoint.indexOf( '?' ) > -1 ? '&' : '?' ) + q.toString(), { credentials: 'omit' } )
.then( function ( r ) { return r.json(); } )
.then( function ( d ) {
if ( d && typeof d.html === 'string' ) {
results.innerHTML = d.html;
}
} )
.catch( function () {
results.innerHTML = '<p class="m-dek m-area__empty">লোড করা যায়নি, আবার চেষ্টা করুন।</p>';
} )
.then( function () {
results.removeAttribute( 'aria-busy' );
results.style.opacity = '';
} );
}
function schedule( form ) {
clearTimeout( timers.get( form ) );
timers.set( form, setTimeout( function () { load( form ); }, 150 ) );
}
document.addEventListener( 'change', function ( e ) {
var t = e.target;
if ( ! t.classList ) {
return;
}
if ( t.classList.contains( 'meeha-area-division' ) ) {
var dis = target( t );
fill( dis, areaData().d[ t.value ], 'জেলা' );
if ( dis ) {
fill( target( dis ), [], 'থানা/উপজেলা' );
}
} else if ( t.classList.contains( 'meeha-area-district' ) ) {
var upz = target( t );
if ( upz ) {
fill( upz, areaData().u[ t.value ], 'থানা/উপজেলা' );
}
}
var form = t.closest && t.closest( 'form[data-meeha-area]' );
if ( form ) {
schedule( form );
}
} );
document.addEventListener( 'submit', function ( e ) {
var form = e.target.closest && e.target.closest( 'form[data-meeha-area]' );
if ( form ) {
e.preventDefault();
load( form );
}
} );
document.querySelectorAll( 'form[data-meeha-area] [data-js-hide]' ).forEach( function ( b ) {
b.style.display = 'none';
} );
}() );
;
